const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '单位换算表' },
      { kind: 'text', payload: '项目' },
      { kind: 'text', payload: '内容' },
      { kind: 'text', payload: '物理量' },
      { kind: 'text', payload: '速度' },
      { kind: 'text', payload: '原值' },
      { kind: 'text', payload: '108 km/h' },
      { kind: 'text', payload: '换算关系' },
      { kind: 'text', payload: '1 m/s = 3.6 km/h' },
      { kind: 'text', payload: '换算算式' },
      { kind: 'text', payload: '108 ÷ 3.6 = 30' },
      { kind: 'text', payload: '结果' },
      { kind: 'text', payload: '30.0 m/s' },
      { kind: 'text', payload: '注：结果保留三位有效数字' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var margin = Math.max(14, Math.round(W * 0.05));
    var titleH = 32;
    var tableX = margin;
    var tableW = W - 2 * margin;
    var tableTop = margin + titleH + 8;
    var footH = 26;
    var rows = 6;
    var availH = H - tableTop - margin - footH;
    var rowH = Math.max(24, Math.min(46, availH / rows));
    var tableH = rowH * rows;
    var y0 = tableTop + Math.max(0, (availH - tableH) / 2);
    var labelW = tableW * 0.34;

    function rectPath(x, y, w, h) {
      return visualSdk.polyline([[x, y], [x + w, y], [x + w, y + h], [x, y + h], [x, y]]);
    }

    var paths = [];
    paths.push({ id: 'hdrFill', commands: rectPath(tableX, y0, tableW, rowH) });
    paths.push({ id: 'resFill', commands: rectPath(tableX, y0 + 5 * rowH, tableW, rowH) });
    paths.push({ id: 'outer', commands: rectPath(tableX, y0, tableW, tableH) });
    var i;
    for (i = 1; i < rows; i++) {
      paths.push({ id: 'h' + i, commands: visualSdk.polyline([[tableX, y0 + i * rowH], [tableX + tableW, y0 + i * rowH]]) });
    }
    paths.push({ id: 'v1', commands: visualSdk.polyline([[tableX + labelW, y0], [tableX + labelW, y0 + tableH]]) });

    var children = [];
    children.push({ type: 'path', pathId: 'hdrFill', fill: '#eef2f7' });
    children.push({ type: 'path', pathId: 'resFill', fill: '#f2f7f2' });
    children.push({ type: 'path', pathId: 'outer', fill: 'none', stroke: { width: 1.6, color: '#26354a' } });
    for (i = 1; i < rows; i++) {
      children.push({ type: 'path', pathId: 'h' + i, fill: 'none', stroke: { width: 1, color: '#8fa1b8' } });
    }
    children.push({ type: 'path', pathId: 'v1', fill: 'none', stroke: { width: 1, color: '#8fa1b8' } });

    children.push({
      type: 'label', contentId: 'c0',
      anchor: { x: W / 2, y: margin + titleH / 2 },
      hAlign: 'center', vAlign: 'middle', color: '#1d2b3a'
    });

    var rowsText = [
      ['c1', 'c2'],
      ['c3', 'c4'],
      ['c5', 'c6'],
      ['c7', 'c8'],
      ['c9', 'c10'],
      ['c11', 'c12']
    ];
    var r;
    for (r = 0; r < rowsText.length; r++) {
      var cy = y0 + rowH * (r + 0.5);
      children.push({
        type: 'label', contentId: rowsText[r][0],
        anchor: { x: tableX + 12, y: cy },
        hAlign: 'left', vAlign: 'middle', color: '#1d2b3a'
      });
      children.push({
        type: 'label', contentId: rowsText[r][1],
        anchor: { x: tableX + labelW + 12, y: cy },
        hAlign: 'left', vAlign: 'middle', color: '#1d2b3a'
      });
    }

    children.push({
      type: 'label', contentId: 'c13',
      anchor: { x: tableX, y: y0 + tableH + 14 },
      hAlign: 'left', vAlign: 'middle', color: '#4a5b70'
    });

    return {
      schemaVersion: 1,
      sceneId: 'unit-conversion-table',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
